function updateURL(){const p=new URLSearchParams({lang,term:state.term});for(const k of ['q','city','type','ownership','preferred'])if(state[k]!==defaults[k])p.set(k,state[k]);if(state.known)p.set('known','1');if(state.audited)p.set('audited','1');if(state.weiquan)p.set('weiquan','1');p.set('sort',state.priorities.join(','));try{history.replaceState(null,'','?'+p);}catch{}}
