  body.querySelectorAll('p').forEach(p=>{if(p.querySelector('strong')?.textContent===t('scope')+'：'&&p.textContent.endsWith(t('scopeUnknown')))p.innerHTML='<strong>'+esc(t('scope'))+'：</strong>'+esc(t('scopeGeneral'));});
