function dialogTop(title,subtitle=''){return `<div class="dialog-top"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="close-dialog" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div>`;}
function scopeText(scope){return ({graduate:lang==='zh'?'研究所限定':'ဘွဲ့လွန်သာ',undergraduate:lang==='zh'?'學士班':'ဘွဲ့ကြို', 'selected-programs':lang==='zh'?'指定系所／專班':'သတ်မှတ်ဘာသာရပ်များသာ'})[scope]||'';}
