function showSchool(id){
  const s=schools.find(x=>x.id===id);if(!s)return;const term=s.terms[state.term],admission=term.apply||s.admission;
  showDialog(`${dialogTop(s.short+' '+s.abbr,s.name+(s.english?' · '+s.english:''))}<span class="detail-semester ${state.term}">${esc(t(state.term))} · ${termLabel()}</span><p>${s.cities.map(cityName).map(esc).join(' / ')} · ${esc(t(s.type))} · ${esc(t(s.ownership))}</p>${s.paused?`<div class="notice-strip">${esc(t('paused'))}</div>`:''}${term.rounds.length?term.rounds.map((r,i)=>`<section class="round-card"><h4>${esc(localized(r.name)||t('round')+' '+(i+1))}${scopeText(r.scope)?' · '+esc(scopeText(r.scope)):''}</h4><div class="round-grid">${eventHTML(r.start,'start')}${eventHTML(r.end,'end')}${eventHTML(r.result,'result')}</div>${r.note?`<p class="detail-note">${esc(localized(r.note))}</p>`:''}</section>`).join(''):`<p class="detail-note">${esc(t('unknownNote'))}</p>`}${historyHTML(term)}${term.scope?`<p><strong>${esc(t('scope'))}：</strong>${esc(term.scope==='graduate'?t('graduate'):localized(term.scopeLabel)||t('scopeUnknown'))}</p>`:''}${(term.notes||[]).map(n=>`<p class="detail-note">${esc(localized(n))}${lang==='my'&&n.zh?`<br><span lang="zh-Hant">${esc(n.zh)}</span>`:''}</p>`).join('')}<h3>${esc(t('programs'))}</h3>${term.programs?.length?`<ul>${term.programs.map(n=>`<li>${esc(localized(n))}</li>`).join('')}</ul>`:''}${term.programLink?`<div class="detail-links">${link(term.programLink,t('programs'),'primary')}</div>`:''}${term.brochure?`<div class="detail-links">${link(term.brochure.url,t(term.brochure.status==='official'?'brochure':'oldBrochure')+(term.brochure.academicYear?' · '+term.brochure.academicYear:''),'primary')}</div>`:`<p>${esc(t('noBrochure'))}</p>`}<p class="detail-note">${esc(t('catalogNote'))}</p><div class="detail-links">${s.catalog?link(s.catalog,t('catalog')):''}${link(admission?.url||s.website,t(admission?.kind==='apply'?'apply':admission?.kind==='admission'?'portal':'home'),'primary')}</div><h3>${esc(t('allSources'))}</h3>${[...new Set([...(term.sources||[]),...(term.brochure?[term.brochure.url]:[]),s.website])].map((u,i)=>`<a class="source-item" href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(new URL(u).hostname)} ${icon('arrow')}</a>`).join('')}<p class="detail-note">${esc(t('letterNote'))}</p><div class="detail-footer">${esc(t('checked'))}: ${s.checked||data.updated} · ${esc(t('difficulty'))}: ${s.difficulty?s.difficulty+'/5':t('notEvaluated')}<br>${esc(t('difficultyNote'))}</div>${renderInsights(insights[s.id],state.term,lang,esc,safeURL)}`);
}
function coverageHTML(){
 if(!data.coverage)return '';
 return ['fall','spring'].map(tm=>{const c=data.coverage[tm];return `<section class="coverage-block"><h3>${esc(t(tm))}</h3><div class="coverage-counts">${['official','historical','estimated','unknown'].map(k=>`<span>${esc(t(k))} <strong>${c.counts[k]}</strong></span>`).join('')}</div><details><summary>${esc(t('unknown'))} · ${c.counts.unknown}</summary><p>${c.schools.unknown.map(s=>esc(s.name+' '+s.abbr)).join('、')}</p></details></section>`;}).join('');
}
function showSources(){const known=schools.filter(s=>['spring','fall'].some(tm=>s.terms[tm].rounds.some(r=>eventKey(r.start)||eventKey(r.end)||eventKey(r.result)))).length;const official=schools.filter(s=>['spring','fall'].some(tm=>s.terms[tm].rounds.some(r=>[r.start,r.end,r.result].some(e=>e?.status==='official')))).length;showDialog(`${dialogTop(t('sources'),t('checked')+': '+data.updated)}<div class="methodology-grid"><div class="stat"><strong>${schools.length}</strong>${esc(t('schoolCount'))}</div><div class="stat"><strong>${known}</strong>${esc(t('scheduled'))}</div><div class="stat"><strong>${official}</strong>${esc(t('verified'))}</div></div>${coverageHTML()}<div class="detail-links">${link(new URL('./coverage-report.html',location.href).href,lang==='zh'?'完整補全報告與待核清單':'အချက်အလက်ဖြည့်စွက်မှု အစီရင်ခံစာ')}</div><div class="detail-links">${link(new URL('./taichung-audit.html',location.href).href,lang==='zh'?'臺中11校最新核對與缺口':'ထိုင်ချုံး 11 ကျောင်း စစ်ဆေးမှုနှင့် လိုအပ်ချက်များ')}</div><div class="detail-links">${link(new URL('./national-audit.html',location.href).href,lang==='zh'?'彰師・暨南・聯合等17校核對與缺口':'နောက်ထပ် 17 ကျောင်း စစ်ဆေးမှုနှင့် လိုအပ်ချက်များ')}</div><div class="detail-links">${link(new URL('./remaining-national-audit.html',location.href).href,lang==='zh'?'新增23所國立大學／科大核對與缺口':'နောက်ထပ် အစိုးရတက္ကသိုလ် 23 ကျောင်း စစ်ဆေးမှုနှင့် လိုအပ်ချက်များ')}</div><h3>${esc(t('coverage'))}</h3><p>${esc(t('coverageNote'))}</p><p class="detail-note">${esc(t('unknownCount'))}: ${schools.length-known} ${esc(t('schoolCount'))}</p><h3>${esc(t('start'))} / ${esc(t('result'))}</h3><p>${esc(t('dateNote'))}</p><h3>${esc(t('difficulty'))}</h3><p>${esc(t('difficultyNote'))}</p><div class="detail-links">${link('https://data.gov.tw/dataset/6091',t('registryLink'))}${link('https://www.studyintaiwan.org/how-to-apply/school','Study in Taiwan')}${link('https://www.cac.edu.tw/','大學甄選入學委員會')}${link('https://www.jctv.ntut.edu.tw/','技專校院招生委員會')}</div><p class="detail-note">${esc(t('notLive'))}</p>`);}
function toast(msg,undo=false){const n=document.querySelector('#toast');n.innerHTML=`<span>${esc(msg)}</span>${undo?`<button data-action="undo-save">${esc(t('undo'))}</button>`:''}`;n.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('visible'),undo?9000:4000);}
function exportSaved(){const rows=schools.filter(s=>saved.includes(s.id));if(!rows.length)return toast(t('exportEmpty'));const value=e=>e?.date||localized(e?.label)||t('pending');const csv=[['學校','簡稱','城市','學期','開始申請','開始狀態','申請截止','截止狀態','放榜','放榜狀態','來源年度','原始開始','原始截止','原始放榜','日期來源','開始適用範圍','截止適用範圍','放榜適用範圍','官方入口','查核日'],...rows.map(s=>{const a=firstEvent(s,state.term,'start'),e=firstEvent(s,state.term,'end'),r=firstEvent(s,state.term,'result');return [s.name,s.abbr,s.cities.join('/'),termLabel(),value(a),a?.status||'unknown',value(e),e?.status||'unknown',value(r),r?.status||'unknown',[a,e,r].map(x=>x?.sourceYear||x?.basis||'').join(' / '),a?.rawDate||a?.date||'',e?.rawDate||e?.date||'',r?.rawDate||r?.date||'',[a,e,r].map(x=>x?.sourceUrl||'').filter(Boolean).join(' / '),a?.scope||'',e?.scope||'',r?.scope||'',(s.terms[state.term].apply||s.admission)?.url||s.website,data.updated];})].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='Taiwan-shortlist-'+state.term+'-2027.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{
  const mapTarget=e.target.closest('[data-map-city]');
  if(mapTarget){const city=mapTarget.dataset.mapCity;if(city&&!cities.includes(city))return;state.city=city;state.page=1;mapExpanded=true;render();const map=document.querySelector('.map-panel');[...map.querySelectorAll('[data-map-city]')].find(n=>n.dataset.mapCity===city&&n.tagName.toLowerCase()===mapTarget.tagName.toLowerCase())?.focus({preventScroll:true});return;}
  if(e.target.closest('[data-action="map-results"]')){mapExpanded=false;renderMap();document.querySelector('#results').scrollIntoView({block:'start'});document.querySelector('#results').focus({preventScroll:true});return;}
  const historyBadge=e.target.closest('[data-history]');if(historyBadge){historyBadge.focus({preventScroll:true});openHistory(historyBadge.dataset.history);return;}const b=e.target.closest('button');if(!b)return;
  if(b.dataset.removeFilter){const k=b.dataset.removeFilter;state[k]=k==='known'||k==='audited'||k==='weiquan'||k==='favorites'?false:k==='type'||k==='ownership'?'all':'';state.page=1;render();document.querySelector('#results').focus({preventScroll:true});return;}
  if(b.dataset.action==='text-size'){largeText=!largeText;persist('tsf-large-text',largeText);render();return;}
  if(b.dataset.action==='clear-search'){state.q='';state.page=1;render();document.querySelector('#search').focus({preventScroll:true});return;}
  if(b.dataset.action==='apply-filters'){expanded=false;render();document.querySelector('#results').scrollIntoView({block:'start'});document.querySelector('#results').focus({preventScroll:true});return;}
  if(b.dataset.action==='undo-save'&&lastBookmark){saved=lastBookmark;lastBookmark=null;persist('tsf-saved',saved);render();document.querySelector('#toast').classList.remove('visible');document.querySelector('#results').focus({preventScroll:true});return;}
  if(b.dataset.lang){lang=b.dataset.lang;persist('tsf-lang',lang);render();return;}
  if(b.dataset.term){state.term=b.dataset.term;state.page=1;render();return;}
  if(b.dataset.save){const id=b.dataset.save,removing=saved.includes(id);lastBookmark=[...saved];saved=removing?saved.filter(x=>x!==id):[...saved,id];persist('tsf-saved',saved);render();toast(t(removing?'removed':'added'),true);if(!document.querySelector('[data-save="'+id+'"]'))document.querySelector('#results').focus({preventScroll:true});return;}
  if(b.dataset.action==='weiquan'){state={...defaults,term:state.term,weiquan:true,priorities:[...defaults.priorities]};render();showWeiquan();return;}
  if(b.dataset.action==='wq-back'){showWeiquan();return;}
  if(b.dataset.wqStep){const [y,m]=wqMonth.split('-').map(Number);wqMonth=new Date(Date.UTC(y,m-1+Number(b.dataset.wqStep),1)).toISOString().slice(0,7);showWeiquan();return;}
  if(b.dataset.detail){const back=wqActive&&dialog.open;if(b.dataset.detailTerm){state.term=b.dataset.detailTerm;render();}showSchool(b.dataset.detail);if(back)document.querySelector('.dialog-inner').prepend(makeElement(`<button class="wq-back" data-action="wq-back">← 偉銓 · ${lang==='zh'?'返回月份':'လစဉ်အစီအစဉ်သို့ ပြန်ရန်'}</button>`));return;}
  if(b.dataset.page){state.page=Number(b.dataset.page);renderResults();document.querySelector('#results').scrollIntoView({block:'start'});document.querySelector('#results').focus({preventScroll:true});return;}
  if(b.dataset.preset){state.priorities=b.dataset.preset==='city'?['city','difficulty-desc','result']:b.dataset.preset==='start'?['start','city','difficulty-desc']:['result','city','difficulty-desc'];if(b.dataset.preset==='city')state.preferred='臺中市';state.page=1;render();return;}
  switch(b.dataset.action){case 'close':dialog.close();break;case 'filters':expanded=!expanded;render();break;case 'audited':state.audited=!state.audited;state.page=1;render();break;case 'favorites':state.favorites=!state.favorites;state.page=1;render();break;case 'reset':state={...defaults,term:state.term,priorities:[...defaults.priorities]};render();break;case 'sources':showSources();break;case 'export':exportSaved();break;case 'share':try{await navigator.clipboard.writeText(location.href);toast(t('copied'));}catch{toast(t('copyFailed'));}break;}
});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.dataset.history){e.preventDefault();openHistory(e.target.dataset.history);}if(['Enter',' '].includes(e.key)&&e.target.matches('g[data-map-city]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{const n=e.target;if(n.hasAttribute('data-wq-month')){wqMonth=n.value;showWeiquan();return;}if(n.hasAttribute('data-wq-term')){wqTerm=n.value;showWeiquan();return;}if(n.dataset.filter){state[n.dataset.filter]=n.type==='checkbox'?n.checked:n.value;state.page=1;render();}if(n.dataset.priority!==undefined){const i=Number(n.dataset.priority),old=state.priorities[i],duplicate=state.priorities.indexOf(n.value);state.priorities[i]=n.value;if(duplicate!==-1&&duplicate!==i)state.priorities[duplicate]=old;state.page=1;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.q=e.target.value;state.page=1;renderResults();updateURL();}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function makeElement(html){const template=document.createElement('template');template.innerHTML=html;return template.content.firstElementChild;}
function enhanceControls(){
 document.documentElement.classList.toggle('large-text',largeText);
 const skip=document.querySelector('.skip');if(skip)skip.textContent=t('skip');
 const actions=document.querySelector('.header-actions');
 actions.prepend(makeElement(`<button class="plain-btn text-size" data-action="text-size" aria-pressed="${largeText}" aria-label="${esc(t(largeText?'normalText':'largeText'))}" title="${esc(t(largeText?'normalText':'largeText'))}">A<span aria-hidden="true">${largeText?'−':'+'}</span></button>`));
 const favorite=actions.querySelector('[data-action="favorites"]');favorite.setAttribute('aria-label',t('saved')+' · '+saved.length);
 document.querySelectorAll('[data-lang]').forEach(n=>n.setAttribute('lang',n.dataset.lang==='my'?'my':'zh-Hant'));
 const sidebar=document.querySelector('.sidebar');sidebar.id='school-filters';
 document.querySelector('[data-action="filters"]').setAttribute('aria-controls','school-filters');
 sidebar.append(makeElement(`<button class="primary apply-filters" data-action="apply-filters">${esc(t('viewResults'))} · ${visible.length}</button>`));
 const box=document.querySelector('.sortbox'),row=box.querySelector('.sort-row'),note=box.querySelector('.sort-note');
 const disclosure=makeElement(`<details class="sort-disclosure" ${sortExpanded?'open':''}><summary>${esc(t('advancedSort'))}</summary></details>`);
 disclosure.append(row,note);box.append(disclosure);
 disclosure.addEventListener('toggle',()=>{sortExpanded=disclosure.hasAttribute('open');});
 const presetOrders={city:['city','difficulty-desc','result'],start:['start','city','difficulty-desc'],result:['result','city','difficulty-desc']};
 box.querySelectorAll('[data-preset]').forEach(n=>n.setAttribute('aria-pressed',String(JSON.stringify(state.priorities)===JSON.stringify(presetOrders[n.dataset.preset])&&(n.dataset.preset!=='city'||state.preferred==='臺中市'))));
 box.querySelector('.sort-heading strong').textContent=sortLabel(state.priorities[0]);
 document.querySelector('.searchbar').append(makeElement(`<button class="clear-search" data-action="clear-search" aria-label="${esc(t('clearSearch'))}" ${state.q?'':'hidden'}>${icon('close')}</button>`));
}
function renderResults(){
 renderResultsBase();
 const result=document.querySelector('#results');
 const count=schools.filter(s=>['audited','partially_audited'].includes(s.reviewState)).length;
 result.prepend(makeElement(`<div class="audited-shortcut"><button data-action="audited" aria-pressed="${state.audited}" class="${state.audited?'selected':''}">${icon('check')} ${bilingual('audited')} <span>${count}</span></button><small>${esc(t('auditedNote'))}</small></div>`));
 result.prepend(makeElement(`<div class="weiquan-shortcut"><button data-action="weiquan" aria-pressed="${state.weiquan}">偉銓 <span>${schools.filter(s=>s.weiquan).length}</span></button><small>${lang==='zh'?'我的學校 · 按月看開始、截止、放榜':'ကိုယ့်ကျောင်းများ · လစဉ် လျှောက်လွှာနှင့် ရလဒ်'}</small><a class="weiquan-board-link" href="./weiquan.html?lang=${lang}">${lang==='zh'?'偉銓選校板：現在能報、第一年費用、獎學金 →':'偉銓 ကျောင်းရွေးဘုတ် →'}</a></div>`));
 const chips=[];
 if(state.q)chips.push(['q',state.q]);
 if(state.city)chips.push(['city',cityName(state.city)]);
 if(state.type!=='all')chips.push(['type',t(state.type)]);
 if(state.ownership!=='all')chips.push(['ownership',t(state.ownership)]);
 if(state.known)chips.push(['known',t('known')]);
 if(state.weiquan)chips.push(['weiquan','偉銓']);
 if(state.audited)chips.push(['audited',t('audited')]);
 if(state.favorites)chips.push(['favorites',t('saved')]);
 if(chips.length)result.prepend(makeElement(`<div class="active-filters" aria-label="${esc(t('filter'))}">${chips.map(([key,label])=>`<button data-remove-filter="${key}" aria-label="${esc(t('removeFilter')+': '+label)}">${esc(label)} ${icon('close')}</button>`).join('')}</div>`));
 const clear=document.querySelector('.clear-search');if(clear)clear.hidden=!state.q;
 if(!visible.length&&state.favorites&&!saved.length){result.querySelector('.empty h3').textContent=t('emptySaved');result.querySelector('.empty p').textContent=t('emptySavedNote');result.querySelector('.empty button').textContent=t('browseAll');}
 const heading=result.querySelector('.results-heading h2');heading.setAttribute('aria-live','polite');heading.setAttribute('aria-atomic','true');
 result.querySelectorAll('[data-history]').forEach(n=>n.setAttribute('aria-label',t('historyDetails')+' · '+schools.find(s=>s.id===n.dataset.history)?.short));
 result.querySelectorAll('.source-status.historical').forEach(n=>{n.title=t('historicalNote');});
 const pagination=result.querySelector('.pagination');if(pagination)pagination.setAttribute('aria-label',lang==='zh'?'學校清單分頁':'ကျောင်းစာရင်း စာမျက်နှာများ');
 renderMap();
}
function renderMap(){
 const candidates=selectSchools(schools,{...state,city:''},saved),counts={all:candidates.length};
 for(const c of cities)counts[c]=candidates.filter(s=>s.cities.includes(c)).length;
 const panel=makeElement(mapMarkup({lang,selected:state.city,counts,cities:data.cities,open:mapExpanded}));
 const current=document.querySelector('.map-panel');if(current)current.replaceWith(panel);else document.querySelector('.termbar').after(panel);
 panel.addEventListener('toggle',()=>{if(panel.isConnected)mapExpanded=panel.hasAttribute('open');});
 const list=panel.querySelector('.map-city-list');if(mapListExpanded||window.matchMedia?.('(min-width:801px)').matches)list.setAttribute('open','');
 list.addEventListener('toggle',()=>{if(list.isConnected)mapListExpanded=list.hasAttribute('open');});
}
dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');if(dialogTrigger?.isConnected)dialogTrigger.focus({preventScroll:true});});
function registerTools(){
  if(!document.modelContext?.registerTool)return;
  const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});
  const brief=s=>({id:s.id,name:s.name,abbr:s.abbr,cities:s.cities,semester:state.term,start:firstEvent(s,state.term,'start'),result:firstEvent(s,state.term,'result'),url:(s.terms[state.term].apply||s.admission)?.url||s.website});
  const tools=[{name:'filter_taiwan_schools',title:'Filter Taiwan universities',description:'Update the visible school filters and three sorting priorities. Does not apply to any university.',inputSchema:{type:'object',properties:{term:{enum:['spring','fall']},q:{type:'string'},city:{type:'string'},preferred:{type:'string'},type:{enum:['all','university','technology','college','junior']},ownership:{enum:['all','public','private']},known:{type:'boolean'},audited:{type:'boolean'},weiquan:{type:'boolean'},favorites:{type:'boolean'},priorities:{type:'array',items:{enum:SORTS},minItems:3,maxItems:3,uniqueItems:true}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{const patch=validateFilter(input,cities);state={...state,...patch,page:1};render();return {count:visible.length,firstSchools:visible.slice(0,12).map(brief)};}},{name:'read_school_results',title:'Read filtered schools',description:'Read the currently filtered school list and date provenance without changing the interface.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('No arguments expected');return {semester:state.term,count:visible.length,schools:visible.map(brief)};}}];
  for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}
}
try{
 largeText=localRead('tsf-large-text',false)===true;
 const [r,ir]=await Promise.all([fetch('./schools.json'),fetch('./school-insights.json')]);if(!r.ok)throw new Error('data');data=await r.json();schools=data.schools;cities=Object.keys(data.cities);if(ir.ok){const additional=await ir.json();insights=additional.schools||{};}
 const p=new URLSearchParams(location.search);lang=['zh','my'].includes(p.get('lang'))?p.get('lang'):localRead('tsf-lang','my');if(!['zh','my'].includes(lang))lang='my';saved=localRead('tsf-saved',[]);if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>schools.some(s=>s.id===id));
 const initial={};for(const k of ['term','q','city','type','ownership','preferred'])if(p.has(k))initial[k]=p.get(k);if(p.has('known'))initial.known=p.get('known')==='1';if(p.has('audited'))initial.audited=p.get('audited')==='1';if(p.has('weiquan'))initial.weiquan=p.get('weiquan')==='1';if(p.has('sort'))initial.priorities=p.get('sort').split(',');try{Object.assign(state,validateFilter(initial,cities));}catch{}
 render();registerTools();
}catch(error){app.innerHTML='<main class="loading"><h1>資料載入失敗 / အချက်အလက် မတင်နိုင်ပါ</h1><p>請重新整理 / စာမျက်နှာကို ပြန်ဖွင့်ပါ။</p><a href="https://www.studyintaiwan.org/how-to-apply/school">Study in Taiwan ↗</a></main>';console.error('School data could not be loaded',error);}

dialog.addEventListener('close',()=>{wqActive=false;});
